(function(){
 'use strict';
 const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const text=(x,y,t,size=22)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="#36534b">${esc(t)}</text>`;
 const line=(a,b,color='#547f7b',width=4,extra='')=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${color}" stroke-width="${width}" ${extra}/>`;
 const poly=p=>`<polygon points="${p.map(x=>x.join(',')).join(' ')}" fill="#dcece4" stroke="#547f7b" stroke-width="3"/>`;
 const arc=(p,a,b,r=30)=>{const u=a.map((x,i)=>x-p[i]),w=b.map((x,i)=>x-p[i]),nu=Math.hypot(...u),nw=Math.hypot(...w);let d=Math.atan2(w[1],w[0])-Math.atan2(u[1],u[0]);while(d>Math.PI)d-=2*Math.PI;while(d< -Math.PI)d+=2*Math.PI;return `<path d="M${p[0]+u[0]/nu*r} ${p[1]+u[1]/nu*r}A${r} ${r} 0 0 ${d>0?1:0} ${p[0]+w[0]/nw*r} ${p[1]+w[1]/nw*r}" fill="none" stroke="#c49268" stroke-width="2"/>`;};
 const mark=(p,a,b,label)=>{const v=a.map((x,i)=>(x-p[i])/Math.hypot(a[0]-p[0],a[1]-p[1])),w=b.map((x,i)=>(x-p[i])/Math.hypot(b[0]-p[0],b[1]-p[1])),n=Math.hypot(v[0]+w[0],v[1]+w[1]);return arc(p,a,b)+text(p[0]+(v[0]+w[0])/n*52,p[1]+(v[1]+w[1])/n*52+7,label,22);};
 const labels=(p,vals)=>p.map((x,i)=>mark(x,p[(i+p.length-1)%p.length],p[(i+1)%p.length],vals[i]==null?'?':vals[i]+'°')).join('');
 function triangle(a,b){let h=300/(1/Math.tan(a*Math.PI/180)+1/Math.tan(b*Math.PI/180)),scale=Math.min(1,200/h),base=300*scale;h*=scale;const p=[[225-base/2,270],[225+base/2,270],[225-base/2+h/Math.tan(a*Math.PI/180),270-h]];return {p,body:poly(p)+labels(p,[a,b,null])};}
 function draw(v){
  if(v.kind==='angleCards'){const n=v.items.length,w=n*230;return {box:`0 0 ${w} 300`,body:v.items.map((a,i)=>{const p=[115,175],len=a.length||65,point=t=>[p[0]+len*Math.cos(t*Math.PI/180),p[1]-len*Math.sin(t*Math.PI/180)],p1=point(a.rotation),p2=point(a.rotation+a.opening);return `<g transform="translate(${i*230} 0)"><rect x="10" y="15" width="210" height="260" rx="18" fill="${i%2?'#f5e6c9':'#e4efe2'}"/>${line(p,p1)}${line(p,p2)}${arc(p,p1,p2,24)}<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#547f7b"/>${text(115,250,a.label,20)}</g>`;}).join(''),alt:'角卡依張開程度繪製，未標角度數；方向與邊長可能不同。'+v.items.map(a=>a.label).join('、')};}
  if(v.kind==='reasoningBoard'){const items=v.items,cols=items.length===1?1:2,rows=Math.ceil(items.length/cols),width=600;return {box:`0 0 600 ${rows*125+30}`,body:items.map((t,i)=>{const x=20+i%cols*(580/cols),y=20+Math.floor(i/cols)*125,cw=560/cols,parts=String(t).match(/.{1,18}/gu)||[''];return `<g transform="translate(${x} ${y})"><rect width="${cw}" height="105" rx="17" fill="${i%2?'#f0e1c5':'#dfeade'}"/>${parts.map((part,j)=>text(cw/2,parts.length>1?40+j*29:61,part,21)).join('')}</g>`;}).join(''),alt:v.caption+'。'+items.join('；')};}
  if(v.kind==='rotatedRectangles')return {box:'0 0 600 300',body:v.rotations.map((a,i)=>`<g transform="translate(${160+i*280} 145) rotate(${a})"><rect x="-85" y="-55" width="170" height="110" rx="1" fill="#e6e7cf" stroke="#547f7b" stroke-width="4"/></g>`).join(''),alt:'兩張彼此分開的完整長方形卡，其中一張旋轉，沒有剪掉任何角。'};
  if(v.kind==='cutCorner'){const p=[[100,230],[100,70],[320,70],[390,140],[390,230]];return {box:'0 0 500 300',body:poly(p)+line([320,70],[390,70],'#b6b7a1',2,'stroke-dasharray="6 5"')+line([390,70],[390,140],'#b6b7a1',2,'stroke-dasharray="6 5"'),alt:'長方形右上角沿斜線剪除，剩下五邊形；虛線是剪掉前的邊界。'};}
  if(v.kind==='splitAngle'){const p=[170,250],pt=a=>[p[0]+190*Math.cos(a*Math.PI/180),p[1]-190*Math.sin(a*Math.PI/180)],a=pt(0),b=pt(v.split),c=pt(v.opening);return {box:'0 0 500 320',body:line(p,a)+line(p,b,'#bd936c')+line(p,c)+arc(p,a,b,55)+arc(p,b,c,72)+text(147,280,'O')+text(250,225,'甲')+text(181,149,'乙'),alt:'三條射線共用頂點 O，甲、乙是相鄰而不重疊的兩個小角，合成外側兩邊的大角。'};}
  if(v.kind==='triangleKnown'){const t=triangle(v.angles[0],v.angles[1]);return {box:'0 0 450 330',body:t.body,alt:'三角形兩個底角都已標示，頂角未知。'};}
  if(v.kind==='twoTriangles')return {box:'0 0 900 370',body:v.triangles.map((a,i)=>`<g transform="translate(${i*450} 0)">${triangle(a[0],a[1]).body}${text(225,340,i?'乙':'甲',24)}</g>`).join(''),alt:'甲、乙兩個三角形，分別依圖上兩個已知角求第三角，再比較。'};
  if(v.kind==='parallelOpposite'){const shift=130/Math.tan(v.known*Math.PI/180),p=[[65,265],[245,265],[245+shift,135],[65+shift,135]];return {box:'0 0 450 330',body:poly(p)+mark(p[0],p[3],p[1],v.known+'°')+mark(p[2],p[1],p[3],'?'),alt:'平行四邊形已知一角 '+v.known+' 度，求相對的角。'};}
  if(v.kind==='quadKnown'){const A=v.angles[0]*Math.PI/180,B=v.angles[1]*Math.PI/180,C=v.angles[2]*Math.PI/180,beta=-(Math.PI-B),gamma=beta-(Math.PI-C),c=[300+170*Math.cos(beta),170*Math.sin(beta)],u=[Math.cos(-A),Math.sin(-A)],w=[Math.cos(gamma),Math.sin(gamma)],t=(c[0]*w[1]-c[1]*w[0])/(u[0]*w[1]-u[1]*w[0]);let p=[[0,0],[300,0],c,u.map(x=>x*t)],minX=Math.min(...p.map(x=>x[0])),minY=Math.min(...p.map(x=>x[1])),maxX=Math.max(...p.map(x=>x[0])),maxY=Math.max(...p.map(x=>x[1])),scale=Math.min(330/(maxX-minX),210/(maxY-minY));p=p.map(([x,y])=>[60+(x-minX)*scale,55+(y-minY)*scale]);return {box:'0 0 450 330',body:poly(p)+labels(p,v.angles),alt:'四邊形已知三個內角 '+v.angles.slice(0,3).join('、')+' 度，第四角未知。'};}
  if(v.kind==='rhombus'){const p=[[80,170],[225,70],[370,170],[225,270]];return {box:'0 0 450 330',body:poly(p)+p.map((a,i)=>{const b=p[(i+1)%4],x=(a[0]+b[0])/2,y=(a[1]+b[1])/2;return line([x-5,y-6],[x+5,y+6],'#b78e65',3);}).join(''),alt:'斜放的菱形，四邊有相同等長記號，沒有直角標記。'};}
  if(v.kind==='rectangleDimensions')return {box:'0 0 500 300',body:'<rect x="80" y="70" width="300" height="160" fill="#e2ece0" stroke="#547f7b" stroke-width="3"/>'+text(230,45,v.width+' 公分')+text(430,165,v.height+' 公分'),alt:'長方形兩鄰邊 '+v.width+' 與 '+v.height+' 公分；邊長示意未按比例。'};
  return null;
 }
 window.ReasoningVisuals={draw};
})();
